window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["wise"]={html:"<div class=\"own-wise\">\n  <header class=\"wi-nav\">\n    <a class=\"wi-brand\" href=\"#wi-top\">\n      <span class=\"wi-mark\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 32 32\"><path d=\"M5 6h13l-4 6h5l-3 6h5L13 28H7l5-10H7l4-6H5z\" fill=\"#0e0f0c\"/></svg>\n      </span>\n      <span class=\"wi-brand-name\">Northwind</span>\n    </a>\n    <nav class=\"wi-nav-links\" aria-label=\"Primary\">\n      <a href=\"#wi-product\">Product</a>\n      <a href=\"#wi-regions\">Regions</a>\n      <a href=\"#wi-pricing\">Pricing</a>\n    </nav>\n    <div class=\"wi-nav-actions\">\n      <a class=\"wi-link\" href=\"#\">Log in</a>\n      <a class=\"wi-btn wi-btn-primary wi-btn-sm\" href=\"#wi-cta\">Open an account</a>\n    </div>\n  </header>\n\n  <main>\n    <section class=\"wi-hero\" id=\"wi-top\" aria-labelledby=\"wiHeroH\">\n      <div class=\"wi-hero-copy\">\n        <p class=\"wi-eyebrow\">Operations analytics</p>\n        <h1 class=\"wi-hero-title\" id=\"wiHeroH\">Move the numbers that move the floor</h1>\n        <p class=\"wi-hero-lead\">Northwind gives operations teams one live board for throughput, regions and shifts — modelled, governed and ready before the next stand-up.</p>\n        <div class=\"wi-hero-cta\">\n          <a class=\"wi-btn wi-btn-primary\" href=\"#wi-cta\">Get started free</a>\n          <a class=\"wi-btn wi-btn-tertiary\" href=\"#wi-pricing\">See pricing</a>\n        </div>\n        <ul class=\"wi-trust\">\n          <li><b>5</b> regions live</li>\n          <li><b>97%</b> on-time</li>\n          <li><b>2 min</b> to a board</li>\n        </ul>\n      </div>\n\n      <div class=\"wi-converter\" role=\"group\" aria-label=\"Throughput estimator\">\n        <div class=\"wi-conv-head\">\n          <span class=\"wi-conv-title\">Throughput estimator</span>\n          <span class=\"wi-badge wi-badge-live\">Live</span>\n        </div>\n        <div class=\"wi-conv-field\">\n          <label class=\"wi-conv-label\" for=\"wiFrom\">Regions</label>\n          <div class=\"wi-conv-input\">\n            <input id=\"wiFrom\" type=\"number\" min=\"1\" max=\"12\" step=\"1\" value=\"3\" inputmode=\"numeric\" data-wi-regions>\n            <span class=\"wi-conv-unit\">regions</span>\n          </div>\n        </div>\n        <span class=\"wi-conv-swap\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M7 4v14M7 4L3 8m4-4 4 4M17 20V6m0 14 4-4m-4 4-4-4\"/></svg>\n        </span>\n        <div class=\"wi-conv-field\">\n          <span class=\"wi-conv-label\">Estimated throughput</span>\n          <span class=\"wi-conv-out\" data-wi-out>18,420</span>\n        </div>\n        <div class=\"wi-conv-foot\">\n          <span class=\"wi-conv-rate\" data-wi-rate>= 0.97 on-time</span>\n          <a class=\"wi-btn wi-btn-primary wi-btn-sm\" href=\"#wi-cta\">Start free</a>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"wi-cards-sec\" id=\"wi-product\" aria-labelledby=\"wiProdH\">\n      <div class=\"wi-sec-head\">\n        <p class=\"wi-eyebrow\">The platform</p>\n        <h2 class=\"wi-sec-title\" id=\"wiProdH\">Everything the floor runs on</h2>\n      </div>\n      <div class=\"wi-card-grid\">\n        <article class=\"wi-card wi-card-green\">\n          <span class=\"wi-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 18V8m5 10V4m5 14v-7m5 7V6\"/></svg>\n          </span>\n          <h3>Live throughput</h3>\n          <p>A single governed metric — no reconciliation, no re-keyed totals, no overnight surprises.</p>\n        </article>\n        <article class=\"wi-card wi-card-sage\">\n          <span class=\"wi-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 4v8l6 3\"/></svg>\n          </span>\n          <h3>Shift-aware alerts</h3>\n          <p>Thresholds respect the roster, so the right supervisor is paged at the right hour.</p>\n        </article>\n        <article class=\"wi-card wi-card-dark\">\n          <span class=\"wi-ico wi-ico-dark\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 7h16M4 12h10M4 17h13\"/></svg>\n          </span>\n          <h3>Regional roll-ups</h3>\n          <p>Five regions, one true total. Every roll-up traces back to its source stream.</p>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"wi-band\" id=\"wi-regions\" aria-labelledby=\"wiRegH\">\n      <div class=\"wi-sec-head\">\n        <p class=\"wi-eyebrow\">By region</p>\n        <h2 class=\"wi-sec-title\" id=\"wiRegH\">Where the volume sits</h2>\n      </div>\n      <div class=\"wi-band-cards\">\n        <div class=\"wi-stat\">\n          <span class=\"wi-stat-label\">Northwest</span>\n          <span class=\"wi-stat-num\" data-wi-count=\"18420\">18,420</span>\n          <span class=\"wi-badge wi-badge-positive\">On track</span>\n        </div>\n        <div class=\"wi-stat\">\n          <span class=\"wi-stat-label\">Eastern Seaboard</span>\n          <span class=\"wi-stat-num\" data-wi-count=\"15870\">15,870</span>\n          <span class=\"wi-badge wi-badge-positive\">On track</span>\n        </div>\n        <div class=\"wi-stat\">\n          <span class=\"wi-stat-label\">Gulf Coast</span>\n          <span class=\"wi-stat-num\" data-wi-count=\"12240\">12,240</span>\n          <span class=\"wi-badge wi-badge-soft\">Watch</span>\n        </div>\n        <div class=\"wi-stat\">\n          <span class=\"wi-stat-label\">Pacific</span>\n          <span class=\"wi-stat-num\" data-wi-count=\"14030\">14,030</span>\n          <span class=\"wi-badge wi-badge-positive\">On track</span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"wi-pricing\" id=\"wi-pricing\" aria-labelledby=\"wiPriceH\">\n      <div class=\"wi-sec-head\">\n        <p class=\"wi-eyebrow\">Pricing</p>\n        <h2 class=\"wi-sec-title\" id=\"wiPriceH\">Plans that grow with the floor</h2>\n      </div>\n      <div class=\"wi-price-grid\">\n        <article class=\"wi-price-card\">\n          <h3>Starter</h3>\n          <p class=\"wi-price\"><span>$0</span> / mo</p>\n          <p class=\"wi-price-lead\">One board, one region.</p>\n          <ul class=\"wi-feats\"><li>1 live board</li><li>3 streams</li><li>7-day history</li></ul>\n          <a class=\"wi-btn wi-btn-secondary wi-btn-block\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"wi-price-card wi-price-feat\">\n          <span class=\"wi-chip\">Most popular</span>\n          <h3>Growth</h3>\n          <p class=\"wi-price\"><span>$240</span> / mo</p>\n          <p class=\"wi-price-lead\">For multi-region teams.</p>\n          <ul class=\"wi-feats\"><li>Unlimited boards</li><li>40 streams</li><li>Shift-aware alerts</li><li>Versioned history</li></ul>\n          <a class=\"wi-btn wi-btn-primary wi-btn-block\" href=\"#\">Start free trial</a>\n        </article>\n        <article class=\"wi-price-card\">\n          <h3>Scale</h3>\n          <p class=\"wi-price\"><span>Talk to us</span></p>\n          <p class=\"wi-price-lead\">For global networks.</p>\n          <ul class=\"wi-feats\"><li>Everything in Growth</li><li>SSO and audit log</li><li>Dedicated modeler</li></ul>\n          <a class=\"wi-btn wi-btn-tertiary wi-btn-block\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"wi-cta\" id=\"wi-cta\" aria-labelledby=\"wiCtaH\">\n      <div class=\"wi-cta-inner\">\n        <h2 class=\"wi-cta-title\" id=\"wiCtaH\">Ready when the next shift starts</h2>\n        <p class=\"wi-cta-lead\">Free while you build. No card, no sales call.</p>\n        <div class=\"wi-hero-cta\">\n          <a class=\"wi-btn wi-btn-primary\" href=\"#\">Open an account</a>\n          <a class=\"wi-btn wi-btn-outline-inv\" href=\"#\">Book a demo</a>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"wi-footer\">\n    <div class=\"wi-foot-grid\">\n      <div class=\"wi-foot-brand\">\n        <span class=\"wi-brand-name wi-brand-foot\">Northwind</span>\n        <p>Operations analytics for the people running the floor.</p>\n      </div>\n      <nav class=\"wi-foot-col\" aria-label=\"Product\">\n        <h4>Product</h4>\n        <a href=\"#wi-product\">Platform</a>\n        <a href=\"#wi-regions\">Regions</a>\n        <a href=\"#wi-pricing\">Pricing</a>\n      </nav>\n      <nav class=\"wi-foot-col\" aria-label=\"Company\">\n        <h4>Company</h4>\n        <a href=\"#\">About</a>\n        <a href=\"#\">Careers</a>\n        <a href=\"#\">Contact</a>\n      </nav>\n      <nav class=\"wi-foot-col\" aria-label=\"Resources\">\n        <h4>Resources</h4>\n        <a href=\"#\">Docs</a>\n        <a href=\"#\">Status</a>\n        <a href=\"#\">Changelog</a>\n      </nav>\n    </div>\n    <div class=\"wi-foot-base\">\n      <span>Sample data — showcase only</span>\n      <span>&copy; 2026 Northwind</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ WISE — own layout for showcase.html ═══════════════════════════════════\n   Ported from the Wise design language in DESIGN.md: vivid lime-green #9fe870\n   CTA on a sage-tinted canvas #e8ebe6, near-black olive ink #0e0f0c, Wise Sans\n   weight 900 hero (Inter 900 substitute) paired with Inter 600, 24px pill\n   radius on every card + button, surface contrast as the only elevation.\n   Production `vw` → `cqi`, media → `@container frame`, scoped `.own-wise`. */\n\n.own-wise {\n  --wi-green: #9fe870;\n  --wi-green-active: #cdffad;\n  --wi-green-neutral: #c5edab;\n  --wi-green-pale: #e2f6d5;\n  --wi-ink: #0e0f0c;\n  --wi-ink-deep: #163300;\n  --wi-body: #454745;\n  --wi-mute: #868685;\n  --wi-canvas: #ffffff;\n  --wi-canvas-soft: #e8ebe6;\n  --wi-positive: #2ead4b;\n  --wi-positive-deep: #054d28;\n  --wi-warning: #ffd11a;\n  --wi-negative: #d03238;\n  --wi-display: 'Wise Sans', 'Inter', system-ui, -apple-system, sans-serif;\n  --wi-gut: clamp(20px, 4cqi, 48px);\n\n  position: relative;\n  background: var(--wi-canvas-soft);\n  color: var(--wi-ink);\n  font-family: var(--wi-display);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  border-radius: 13px;\n}\n\n.own-wise *, .own-wise *::before, .own-wise *::after { box-sizing: border-box; }\n.own-wise p { margin: 0; }\n.own-wise a { color: inherit; text-decoration: none; }\n.own-wise :focus-visible { outline: 3px solid var(--wi-ink); outline-offset: 2px; border-radius: 6px; }\n.own-wise .wi-eyebrow {\n  font-size: 14px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase;\n  color: var(--wi-body); margin-bottom: 14px;\n}\n.own-wise .wi-sec-title {\n  font-family: var(--wi-display); font-size: clamp(32px, 5cqi, 47px); font-weight: 900;\n  line-height: .96; letter-spacing: -.02em; max-width: 20ch;\n}\n.own-wise .wi-sec-head { max-width: 1200px; margin: 0 auto 36px; }\n\n/* ── buttons ─────────────────────────────────────────────────────────────── */\n.own-wise .wi-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  font-family: var(--wi-display); font-size: 16px; font-weight: 600;\n  padding: 12px 24px; border-radius: 24px; border: 1px solid transparent;\n  cursor: pointer; transition: background-color .18s ease, border-color .18s ease, color .18s ease, transform .18s ease;\n}\n.own-wise .wi-btn:active { transform: translateY(1px); }\n.own-wise .wi-btn-sm { padding: 8px 16px; font-size: 14px; }\n.own-wise .wi-btn-primary { background: var(--wi-green); color: var(--wi-ink); }\n.own-wise .wi-btn-primary:hover { background: var(--wi-green-active); }\n.own-wise .wi-btn-secondary { background: var(--wi-canvas-soft); color: var(--wi-ink); }\n.own-wise .wi-btn-secondary:hover { background: var(--wi-green-neutral); }\n.own-wise .wi-btn-tertiary { background: var(--wi-canvas); color: var(--wi-ink); border-color: var(--wi-ink); }\n.own-wise .wi-btn-tertiary:hover { background: var(--wi-green-pale); }\n.own-wise .wi-btn-block { width: 100%; margin-top: auto; }\n.own-wise .wi-btn-outline-inv { background: transparent; color: var(--wi-green); border-color: var(--wi-green); }\n.own-wise .wi-btn-outline-inv:hover { background: rgba(159,232,112,.12); }\n.own-wise .wi-link { font-size: 14px; font-weight: 600; }\n\n/* ── nav ─────────────────────────────────────────────────────────────────── */\n.own-wise .wi-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px; height: 64px; padding: 0 var(--wi-gut);\n  background: rgba(232,235,230,.92); backdrop-filter: blur(12px);\n  border-bottom: 1px solid rgba(14,15,12,.08);\n}\n.own-wise .wi-brand { display: inline-flex; align-items: center; gap: 9px; }\n.own-wise .wi-mark { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: var(--wi-green); }\n.own-wise .wi-mark svg { width: 20px; height: 20px; }\n.own-wise .wi-brand-name { font-size: 20px; font-weight: 600; letter-spacing: -.02em; }\n.own-wise .wi-nav-links { display: flex; align-items: center; gap: 24px; }\n.own-wise .wi-nav-links a { font-size: 14px; font-weight: 600; color: var(--wi-body); }\n.own-wise .wi-nav-links a:hover { color: var(--wi-ink); }\n.own-wise .wi-nav-actions { margin-left: auto; display: flex; align-items: center; gap: 18px; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-wise .wi-hero {\n  display: grid; grid-template-columns: 1.1fr .9fr; gap: 48px; align-items: center;\n  max-width: 1200px; margin: 0 auto; padding: 72px var(--wi-gut) 56px;\n}\n.own-wise .wi-hero-title {\n  font-family: var(--wi-display); font-size: clamp(44px, 8cqi, 96px); font-weight: 900;\n  line-height: .9; letter-spacing: -.03em; max-width: 14ch;\n}\n.own-wise .wi-hero-lead { font-size: clamp(18px, 2cqi, 20px); line-height: 1.5; color: var(--wi-body); max-width: 46ch; margin-top: 22px; }\n.own-wise .wi-hero-cta { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }\n.own-wise .wi-trust { list-style: none; display: flex; gap: 28px; margin: 36px 0 0; padding: 0; }\n.own-wise .wi-trust li { font-size: 14px; color: var(--wi-body); }\n.own-wise .wi-trust b { display: block; font-size: 24px; font-weight: 900; color: var(--wi-ink); letter-spacing: -.02em; }\n\n/* ── converter card (signature) ──────────────────────────────────────────── */\n.own-wise .wi-converter {\n  position: relative; background: var(--wi-canvas); border: 1px solid var(--wi-ink);\n  border-radius: 24px; padding: 24px; display: flex; flex-direction: column; gap: 16px;\n}\n.own-wise .wi-conv-head { display: flex; align-items: center; justify-content: space-between; }\n.own-wise .wi-conv-title { font-size: 18px; font-weight: 600; }\n.own-wise .wi-badge { display: inline-flex; align-items: center; padding: 2px 12px; border-radius: 9999px; font-size: 14px; font-weight: 600; }\n.own-wise .wi-badge-live { background: var(--wi-green-pale); color: var(--wi-positive-deep); }\n.own-wise .wi-badge-positive { background: var(--wi-green-pale); color: var(--wi-positive-deep); }\n.own-wise .wi-badge-soft { background: #fff3cc; color: #6b4a00; }\n.own-wise .wi-conv-field { display: flex; flex-direction: column; gap: 6px; }\n.own-wise .wi-conv-label { font-size: 14px; font-weight: 600; color: var(--wi-body); }\n.own-wise .wi-conv-input {\n  display: flex; align-items: center; gap: 12px; padding: 14px 16px;\n  border: 1px solid rgba(14,15,12,.18); border-radius: 12px; background: var(--wi-canvas);\n}\n.own-wise .wi-conv-input input {\n  width: 100%; border: 0; background: none; font-family: var(--wi-display);\n  font-size: 32px; font-weight: 600; letter-spacing: -.02em; color: var(--wi-ink);\n}\n.own-wise .wi-conv-input input:focus { outline: none; }\n.own-wise .wi-conv-unit { font-size: 14px; font-weight: 600; color: var(--wi-mute); white-space: nowrap; }\n.own-wise .wi-conv-swap {\n  align-self: center; display: grid; place-items: center; width: 40px; height: 40px;\n  border-radius: 9999px; background: var(--wi-green); margin: -6px 0;\n}\n.own-wise .wi-conv-swap svg { width: 20px; height: 20px; fill: none; stroke: var(--wi-ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-wise .wi-conv-out { font-size: 40px; font-weight: 900; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }\n.own-wise .wi-conv-foot {\n  display: flex; align-items: center; justify-content: space-between; gap: 12px;\n  padding-top: 16px; border-top: 1px solid rgba(14,15,12,.1);\n}\n.own-wise .wi-conv-rate { font-size: 14px; color: var(--wi-body); font-weight: 600; }\n\n/* ── feature cards ───────────────────────────────────────────────────────── */\n.own-wise .wi-cards-sec { max-width: 1200px; margin: 0 auto; padding: 56px var(--wi-gut) 16px; }\n.own-wise .wi-card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-wise .wi-card {\n  display: flex; flex-direction: column; gap: 14px; padding: 24px;\n  border-radius: 24px; min-height: 220px;\n}\n.own-wise .wi-card-green { background: var(--wi-green-pale); }\n.own-wise .wi-card-sage { background: var(--wi-canvas); border: 1px solid rgba(14,15,12,.1); }\n.own-wise .wi-card-dark { background: var(--wi-ink); color: var(--wi-green); }\n.own-wise .wi-ico { display: inline-grid; place-items: center; width: 44px; height: 44px; border-radius: 9999px; background: var(--wi-canvas); }\n.own-wise .wi-ico svg { width: 22px; height: 22px; fill: none; stroke: var(--wi-ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-wise .wi-ico-dark { background: rgba(159,232,112,.15); }\n.own-wise .wi-ico-dark svg { stroke: var(--wi-green); }\n.own-wise .wi-card h3 { font-size: 24px; font-weight: 600; letter-spacing: -.02em; }\n.own-wise .wi-card p { font-size: 16px; line-height: 1.5; }\n.own-wise .wi-card-green p, .own-wise .wi-card-sage p { color: var(--wi-body); }\n.own-wise .wi-card-dark p { color: #cfe9c0; }\n\n/* ── regional band ───────────────────────────────────────────────────────── */\n.own-wise .wi-band { max-width: 1200px; margin: 0 auto; padding: 56px var(--wi-gut); }\n.own-wise .wi-band-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }\n.own-wise .wi-stat {\n  display: flex; flex-direction: column; gap: 8px; align-items: flex-start;\n  padding: 24px; border-radius: 24px; background: var(--wi-canvas);\n  border: 1px solid rgba(14,15,12,.08);\n}\n.own-wise .wi-stat-label { font-size: 14px; font-weight: 600; color: var(--wi-body); }\n.own-wise .wi-stat-num { font-size: 32px; font-weight: 900; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-wise .wi-pricing { max-width: 1200px; margin: 0 auto; padding: 56px var(--wi-gut) 24px; }\n.own-wise .wi-price-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: stretch; }\n.own-wise .wi-price-card {\n  position: relative; display: flex; flex-direction: column; gap: 14px; padding: 24px;\n  border-radius: 24px; background: var(--wi-canvas); border: 1px solid rgba(14,15,12,.1);\n}\n.own-wise .wi-price-feat { background: var(--wi-ink); color: var(--wi-green); border-color: var(--wi-ink); }\n.own-wise .wi-chip {\n  position: absolute; top: 20px; right: 20px; padding: 3px 12px; border-radius: 9999px;\n  font-size: 14px; font-weight: 600; background: var(--wi-green); color: var(--wi-ink);\n}\n.own-wise .wi-price-card h3 { font-size: 24px; font-weight: 600; letter-spacing: -.02em; }\n.own-wise .wi-price { font-size: 15px; color: var(--wi-body); }\n.own-wise .wi-price span { font-size: 40px; font-weight: 900; letter-spacing: -.03em; color: var(--wi-ink); }\n.own-wise .wi-price-feat .wi-price { color: #b9d9a6; }\n.own-wise .wi-price-feat .wi-price span { color: var(--wi-green); }\n.own-wise .wi-price-lead { font-size: 14px; color: var(--wi-body); }\n.own-wise .wi-price-feat .wi-price-lead { color: #b9d9a6; }\n.own-wise .wi-feats { list-style: none; margin: 4px 0 8px; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.own-wise .wi-feats li { position: relative; padding-left: 26px; font-size: 16px; color: var(--wi-body); }\n.own-wise .wi-price-feat .wi-feats li { color: #d8ecd0; }\n.own-wise .wi-feats li::before {\n  content: ''; position: absolute; left: 0; top: 6px; width: 16px; height: 16px; border-radius: 9999px;\n  background: var(--wi-green);\n}\n.own-wise .wi-price-feat .wi-btn-primary { color: var(--wi-ink); }\n\n/* ── CTA ─────────────────────────────────────────────────────────────────── */\n.own-wise .wi-cta { padding: 24px var(--wi-gut) 64px; }\n.own-wise .wi-cta-inner {\n  max-width: 1200px; margin: 0 auto; text-align: center; padding: 72px 40px;\n  border-radius: 24px; background: var(--wi-ink); color: var(--wi-canvas);\n}\n.own-wise .wi-cta-title { font-size: clamp(32px, 5cqi, 64px); font-weight: 900; line-height: .95; letter-spacing: -.03em; color: var(--wi-green); }\n.own-wise .wi-cta-lead { font-size: 20px; color: #cfe9c0; margin-top: 16px; }\n.own-wise .wi-cta .wi-hero-cta { justify-content: center; }\n.own-wise .wi-cta .wi-btn-primary { background: var(--wi-green); color: var(--wi-ink); }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-wise .wi-footer { background: var(--wi-ink); color: var(--wi-canvas-soft); padding: 48px var(--wi-gut) 32px; }\n.own-wise .wi-foot-grid { display: grid; grid-template-columns: 1.6fr repeat(3, 1fr); gap: 32px; max-width: 1200px; margin: 0 auto; }\n.own-wise .wi-brand-foot { color: var(--wi-canvas); }\n.own-wise .wi-foot-brand p { font-size: 14px; line-height: 1.6; color: #b7beb2; margin-top: 12px; max-width: 32ch; }\n.own-wise .wi-foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-wise .wi-foot-col h4 { font-size: 14px; font-weight: 600; color: var(--wi-green); margin-bottom: 4px; }\n.own-wise .wi-foot-col a { font-size: 14px; color: #b7beb2; }\n.own-wise .wi-foot-col a:hover { color: var(--wi-canvas); }\n.own-wise .wi-foot-base {\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  max-width: 1200px; margin: 40px auto 0; padding-top: 20px;\n  border-top: 1px solid rgba(255,255,255,.12); font-size: 14px; color: #8a917f;\n}\n\n/* ── responsive — @container frame ───────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-wise .wi-hero { grid-template-columns: 1fr; gap: 32px; }\n  .own-wise .wi-card-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-wise .wi-band-cards { grid-template-columns: repeat(2, 1fr); }\n  .own-wise .wi-price-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-wise .wi-price-feat { grid-column: span 2; }\n  .own-wise .wi-foot-grid { grid-template-columns: 1fr 1fr; }\n  .own-wise .wi-foot-brand { grid-column: span 2; }\n}\n@container frame (max-width: 760px) {\n  .own-wise .wi-nav-links { display: none; }\n  .own-wise .wi-card-grid { grid-template-columns: 1fr; }\n  .own-wise .wi-band-cards { grid-template-columns: 1fr; }\n  .own-wise .wi-price-grid { grid-template-columns: 1fr; }\n  .own-wise .wi-price-feat { grid-column: span 1; }\n  .own-wise .wi-hero { padding-top: 48px; }\n  .own-wise .wi-trust { flex-wrap: wrap; gap: 20px; }\n  .own-wise .wi-cta-inner { padding: 48px 24px; }\n}\n@container frame (max-width: 430px) {\n  .own-wise .wi-hero-cta { flex-direction: column; }\n  .own-wise .wi-hero-cta .wi-btn { width: 100%; }\n  .own-wise .wi-conv-foot { flex-direction: column; align-items: stretch; }\n  .own-wise .wi-conv-foot .wi-btn { width: 100%; }\n  .own-wise .wi-foot-grid { grid-template-columns: 1fr; }\n  .own-wise .wi-foot-brand { grid-column: span 1; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-wise .wi-btn { transition: none; }\n}\n"};
/* ══ WISE — own layout behaviour for showcase.html ═════════════════════════
   Registers window.OWN_LAYOUTS['wise'].init(root). Drives the hero throughput
   estimator (regions → estimated throughput) and counts the regional figures
   up on first reveal. init returns a cleanup that removes every listener,
   cancels rAF and disconnects observers. Query only inside `root`. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});
  var BASE = 6140;
  var RATE = 0.97;

  OWN['wise'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var cleanups = [];
      var rafs = [];
      var observers = [];

      function on(el, ev, fn) { el.addEventListener(ev, fn); cleanups.push(function () { el.removeEventListener(ev, fn); }); }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }

      /* ── throughput estimator ─────────────────────────────────────────── */
      var regionsInput = root.querySelector('[data-wi-regions]');
      var out = root.querySelector('[data-wi-out]');
      var rateEl = root.querySelector('[data-wi-rate]');
      function fmt(n) { return Math.round(n).toLocaleString('en-US'); }
      function render() {
        var regions = regionsInput ? Math.max(1, Math.min(12, Number(regionsInput.value) || 1)) : 3;
        var value = BASE * regions;
        if (out) out.textContent = fmt(value);
        if (rateEl) rateEl.textContent = '= ' + RATE.toFixed(2) + ' on-time across ' + regions + ' region' + (regions === 1 ? '' : 's');
      }
      if (regionsInput) { on(regionsInput, 'input', render); on(regionsInput, 'change', render); render(); }

      /* ── regional figures count up ────────────────────────────────────── */
      function countTo(el) {
        var target = Number(el.getAttribute('data-wi-count'));
        if (!isFinite(target)) return;
        var start = 0;
        function step(ts) {
          if (!start) start = ts;
          var p = Math.min(1, (ts - start) / 900);
          var eased = 1 - Math.pow(1 - p, 3);
          el.textContent = fmt(target * eased);
          if (p < 1) raf(step);
        }
        raf(step);
      }
      var counts = root.querySelectorAll('[data-wi-count]');
      if (reduced || typeof IntersectionObserver === 'undefined') {
        counts.forEach(function (el) { var t = Number(el.getAttribute('data-wi-count')); if (isFinite(t)) el.textContent = fmt(t); });
      } else {
        var io = new IntersectionObserver(function (entries) {
          entries.forEach(function (en) { if (en.isIntersecting) { countTo(en.target); io.unobserve(en.target); } });
        }, { threshold: .4 });
        counts.forEach(function (el) { io.observe(el); });
        observers.push(io);
      }

      return function cleanup() {
        cleanups.forEach(function (fn) { try { fn(); } catch (e) { /* ignore */ } });
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
